// Code Node: Parse AI Response and Merge with Original Data (FIXED)
const aiResults = $input.all();
const originalArticles = $('Pick most recent 5').all(); // Reference the prepare node

const categorized = aiResults.map((aiItem, index) => {
    let aiResponse;

    try {
        // Get AI response text
        const responseText = aiItem.json.choices?.[0]?.message?.content || 
                           aiItem.json.content?.[0]?.text || 
                           aiItem.json.text || 
                           '{}';

        // Remove markdown code blocks if present
        const cleanJson = responseText
            .replace(/```json\n?/g, '')
            .replace(/```\n?/g, '')
            .trim();

        // Parse JSON
        aiResponse = JSON.parse(cleanJson);

    } catch (error) {
        console.error(`Failed to parse AI response for item ${index}:`, error);
        aiResponse = {
            has_company_mention: false,
            mentioned_companies: [],
            company_count: 0,
            primary_company: null,
            confidence: 'low',
            error: 'Failed to parse AI response'
        };
    }

    // Get corresponding original article from the prepare node
    const originalData = originalArticles[index]?.json?.original_data || {};

    return {
        json: {
            // Original article fields from original_data
            title: originalData.title || '',
            description: originalData.description || '',
            'content:encoded': originalData['content:encoded'] || '',
            pubDate: originalData.pubDate || '',
            url: originalData.url || '',

            // AI Analysis Results
            has_company_mention: aiResponse.has_company_mention || false,
            mentioned_companies: aiResponse.mentioned_companies || [],
            company_count: aiResponse.company_count || 0,
            primary_company: aiResponse.primary_company || null,
            ai_confidence: aiResponse.confidence || 'unknown',

            // Category for routing
            category: aiResponse.has_company_mention ? 'company_mention' : 'general',

            // Metadata
            processed_date: new Date().toISOString(),
            item_index: index,
            analysis_status: aiResponse.error ? 'failed' : 'success'
        }
    };
});

return categorized;

