// Loop through each item in the incoming data
for (const item of items) {
  try {
    const googleUrl = item.json.link;

    // Check if the link exists and contains the Google pattern
    if (googleUrl && googleUrl.includes('google.com/url') && googleUrl.includes('url=')) {

      // Method: Split the string to grab everything after 'url='
      // We use split to handle cases where the URL might not be fully encoded
      let rawSplit = googleUrl.split('url=')[1];

      // If you want the CLEAN link (Recommended - removes &ct, &usg, etc.)
      // We split by '&' to stop where the Google parameters start
      let cleanLink = rawSplit.split('&')[0];

      // Decode the URL just in case it contains %20 or other encoded characters
      cleanLink = decodeURIComponent(cleanLink);

      // Update the item's link field
      item.json.link = cleanLink;
    }

  } catch (error) {
    // If something goes wrong with one link, skip it and continue to the next
    continue;
  }
}

return items;

// Code Node: Get 5 Most Recent Items (Sorted by Date)
const items = $input.all();

// Sort by pubDate (newest first)
const sortedItems = items.sort((a, b) => {
    const dateA = new Date(a.json.pubDate || a.json.date || 0);
    const dateB = new Date(b.json.pubDate || b.json.date || 0);

    // Sort descending (newest first)
    return dateB - dateA;
});

// Take the first 10
const recentItems = sortedItems.slice(0, 5);

return recentItems;

